insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes)
values ('pm-bridges-v1', 'PM-PM', 'PM-APM', 'pm-v1.1', array['Works with product managers to advocate for user needs and prioritise delivery of the greatest value', 'Manages a smaller product with support, or a subset of features of a larger product', 'Learns product management approaches and methods (prioritisation, roadmapping, evidence-based decisions)', 'Works in multidisciplinary teams to plan and deliver product increments']::text[], array['C1', 'C2', 'C3', 'C5', 'C6']::text[], array['C4']::text[], 'The framework expects ''working'' level in product management (including prioritisation and roadmapping), user-centred insight, stakeholder relationships and agile practice, and only ''awareness'' of managing outcomes, so outcome metrics (C4) are only partly developed.', 'open_entry', 'No formal qualifications or experience are stated by the framework; it describes the level as an entry route into digital product roles. Employers set their own criteria.', '{}'::text[], '{}'::text[], 'People moving into product work from other roles, including other digital roles; the framework names business analyst and delivery roles among those that share product manager skills.', 'Suits someone whose profile does not yet show several core product management responsibilities: the role gives supervised ownership of features before owning a product.', 'Associate is a more junior level than Product Manager; for an experienced professional it can mean a step down in level before moving up.', false, array['pm-v1:F1']::text[], '{"pm-v1:F1": "Role levels: associate product manager (skills at working and awareness levels; routes in)"}'::jsonb);
insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes)
values ('pm-bridges-v1', 'PM-PM', 'ROLE-PAN', 'pm-v1.1', array['Analyses product data for product managers, engineers and designers', 'Defines product metrics and builds dashboards that show whether the product is succeeding', 'Finds opportunities in data to improve adoption, retention, engagement or monetisation', 'Helps design, run and evaluate A/B tests on the user journey']::text[], array['C1', 'C4', 'C5', 'X1']::text[], array['X5']::text[], 'Develops learning about users through data (C1), outcome metrics and data-informed decisions (C4), cross-functional work with product teams (C5) and hands-on analytics (X1). It does not involve owning a roadmap (C2), writing requirements (C3) or running delivery (C6).', 'signals', 'One employer framework (GitLab) asks for 3+ years of data analysis, experience with feature and usage metrics and A/B testing, experience supporting a product team, and advanced SQL. Other employers set their own criteria.', array['data_analytics', 'data_science', 'product_analytics']::text[], array['X1']::text[], 'Data analysis, data science or analytics roles, or any background with demonstrated hands-on analytics.', 'Suits someone with analytics evidence whose gaps are in understanding users and owning outcome metrics: the role works on those with product teams every day.', 'An analyst role supports product decisions rather than owning them; a later move is still needed to own a product.', false, array['pm-bridges-v1:B1']::text[], '{"pm-bridges-v1:B1": "Responsibilities and base requirements of the Product Analyst (Intermediate) level"}'::jsonb);
insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes)
values ('pm-bridges-v1', 'PM-PM', 'ROLE-OWNER', 'pm-v1.1', array['Is accountable for maximising the value of the product resulting from the team''s work', 'Develops and communicates the Product Goal', 'Creates and communicates backlog items and orders the backlog', 'Keeps the backlog transparent and understood; stakeholders who want changes must convince the Product Owner']::text[], array['C3', 'C5', 'C6']::text[], array['C2']::text[], 'Develops turning problems into requirements and priorities (C3), stakeholder communication (C5) and iterative delivery (C6). The Product Goal is a step towards product direction (C2, partly). Discovery (C1) and outcome metrics (C4) are not part of the accountability as defined.', 'signals', 'The Scrum Guide states no entry requirements or certifications. Employers set their own criteria.', array['business_analysis']::text[], array['C3']::text[], 'Business analysis, or any background with demonstrated or transferable requirements and prioritisation work.', 'Suits someone whose gaps are in owning priorities and delivery with a team, and who already writes or works with requirements.', 'Employers use ''Product Owner'' in different ways; some roles are backlog administration with little product direction. Check the responsibilities of a specific role.', false, array['pm-bridges-v1:B2']::text[], '{"pm-bridges-v1:B2": "The Product Owner accountability, Product Goal and Product Backlog"}'::jsonb);
insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes)
values ('pm-bridges-v1', 'PM-SPM', 'PM-PM', 'pm-v1.1', array['Owns a product or product area end to end: discovery, direction, priorities, delivery and outcomes', 'Defines and tracks the product''s success measures', 'Works across functions and with stakeholders on the product''s decisions']::text[], array['C1', 'C2', 'C3', 'C4', 'C5', 'C6']::text[], array['L3', 'L4']::text[], 'A Product Manager role is the level below Senior Product Manager in the cited frameworks; it develops every core requirement. Senior differentiators (L1-L4) grow with scope and are only partly developed.', 'target_assessment', 'Assessed with the Product Manager requirements of the approved pack; employers set their own criteria.', '{}'::text[], '{}'::text[], 'Anyone moving into product management for the first time who aims at a senior level.', 'Suits someone without product management experience who targets Senior Product Manager: the frameworks place Product Manager as the level before it.', 'One more move before the senior level.', true, array['pm-v1:F1', 'pm-v1:F4']::text[], '{"pm-v1:F1": "Role levels: product manager, then senior product manager", "pm-v1:F4": "Job family levels: P3 Product Manager, then P4 Senior Product Manager"}'::jsonb);

