-- ------------------------------------------------------------------ D29 structured employer criteria and background families
-- Each update sets only the new columns of exactly one existing pm-v1 row (checked below).
do $$
declare n integer;
begin
  update public.trace_target_role_requirements r set criterion = '{"all": [{"families": ["product_management"], "max": null, "min": 6, "type": "years_in_families"}, {"text": "at least 2 years focused on growth or product-led growth", "type": "stated_condition"}]}'::jsonb, criteria_version = 'pm-eligibility-v1'
   from public.trace_target_role_sources s
